package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.change.*;
import cn.mop.domain.change.ChangeNoticeDraftRepository.*;
import cn.mop.domain.worklog.ManualWorklog;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.context.annotation.Profile;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import static cn.mop.api.ApiResponse.*;
/** Unreviewed draft route, separate from approved change notices and event matching. */
@RestController @RequestMapping("/api/v1/change-notice-drafts") @Profile("remote_test")
public final class ChangeNoticeDraftController {
    static final int MAX_BODY_BYTES=262144;
    private static final long MAX_VERSION=9_007_199_254_740_990L;
    private static final Set<String> FIELDS=Set.of("expected_version","change_summary","asset_ids","planned_start_at","planned_end_at","ticket_id");
    private static final ObjectMapper INPUT=new ObjectMapper(JsonFactory.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(StreamReadConstraints.builder().maxNestingDepth(4).maxStringLength(16000).maxNumberLength(16).build()).build()).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
    private final PlatformRepository platform;private final ChangeNoticeDraftRepository plans;
    public ChangeNoticeDraftController(PlatformRepository platform,ChangeNoticeDraftRepository plans){this.platform=platform;this.plans=plans;}
    @GetMapping Object list(HttpServletRequest request){var a=access(request,false);var q=query(request,Set.of("page_size","before_created_at","before_id"));int size=pageSize(q);if(q.containsKey("before_created_at")!=q.containsKey("before_id"))throw invalid();Instant before=q.containsKey("before_created_at")?ManualWorklog.parseInstant(q.get("before_created_at")):null;String id=q.containsKey("before_id")?uuid(q.get("before_id")):null;var rows=plans.list(a,size+1,before,id);boolean more=rows.size()>size;var items=rows.subList(0,Math.min(size,rows.size()));Snapshot last=more?items.get(items.size()-1):null;return success(map("tenant_id",a.tenantId(),"items",items.stream().map(ChangeNoticeDraftController::summaryDto).toList(),"has_more",more,"next_before_created_at",last==null?null:last.createdAt().toString(),"next_before_id",last==null?null:last.id(),"scope","CURRENT_TENANT_PADMIN","source","postgresql","page_size_limit",20),request);}
    @GetMapping("/{id}") Object get(@PathVariable String id,HttpServletRequest request){var a=access(request,false);query(request,Set.of());return success(dto(plans.get(a,uuid(id))),request);}
    @GetMapping("/{id}/history") Object history(@PathVariable String id,HttpServletRequest request){var a=access(request,false);var q=query(request,Set.of("page_size","before_version"));int size=pageSize(q);String key=uuid(id);Long before=q.containsKey("before_version")?version(q.get("before_version")):null;var rows=plans.history(a,key,size+1,before);boolean more=rows.size()>size;var items=rows.subList(0,Math.min(size,rows.size()));return success(map("tenant_id",a.tenantId(),"notice_id",key,"items",items.stream().map(ChangeNoticeDraftController::revisionDto).toList(),"has_more",more,"next_before_version",more?items.get(items.size()-1).version():null,"scope","CURRENT_TENANT_PADMIN","source","postgresql","page_size_limit",20),request);}
    @PostMapping(consumes=MediaType.APPLICATION_JSON_VALUE) Object create(HttpServletRequest r){access(r,true);return write(null,"CREATE",body(r),r);}
    @PatchMapping(value="/{id}",consumes=MediaType.APPLICATION_JSON_VALUE) Object update(@PathVariable String id,HttpServletRequest r){access(r,true);return write(uuid(id),"UPDATE",body(r),r);}
    @PostMapping(value="/{id}/archive",consumes=MediaType.APPLICATION_JSON_VALUE) Object archive(@PathVariable String id,HttpServletRequest r){access(r,true);return write(uuid(id),"ARCHIVE",body(r),r);}
    @PostMapping(value="/{id}/restore",consumes=MediaType.APPLICATION_JSON_VALUE) Object restore(@PathVariable String id,HttpServletRequest r){access(r,true);return write(uuid(id),"RESTORE",body(r),r);}
    Object write(String id,String action,JsonNode input,HttpServletRequest request){
        var a=access(request,true);query(request,Set.of());if(!Set.of("CREATE","UPDATE","ARCHIVE","RESTORE").contains(action)||(id==null)!=action.equals("CREATE"))throw invalid();String keyId=id==null?null:uuid(id);boolean definition=action.equals("CREATE")||action.equals("UPDATE");fields(input,definition?FIELDS:Set.of("expected_version"));JsonNode v=input.get("expected_version");if(!v.isIntegralNumber()||!v.canConvertToLong())throw invalid();long expected=v.longValue();if(action.equals("CREATE")?expected!=0:expected<1||expected>=MAX_VERSION)throw invalid();var draft=definition?definition(a,input,action.equals("CREATE")?UUID.fromString(a.actorId()):plans.get(a,keyId).draft().applicantId()):null;String key=request.getHeader("Idempotency-Key");if(key==null||!key.matches("[A-Za-z0-9._:-]{1,128}"))throw invalid();
        var result=platform.idempotentAuthorized(a.actorId(),a.tenantId(),request.getMethod()+" "+route(request),key,hash(input),a.permissionVersion(),()->plans.authorizeCurrentAccess(a,keyId),()->dto(switch(action){case "CREATE"->plans.create(a,draft);case "UPDATE"->plans.update(a,keyId,expected,draft);case "ARCHIVE"->plans.archive(a,keyId,expected);case "RESTORE"->plans.restore(a,keyId,expected);default->throw invalid();}));return success(result,request);
    }
    private static ChangeNoticeDraft definition(Access a,JsonNode input,UUID applicant){var ids=input.get("asset_ids");if(!ids.isArray()||ids.isEmpty()||ids.size()>ChangeNoticeDraft.MAX_ASSETS)throw invalid();List<UUID> targets=new ArrayList<>();for(var id:ids)targets.add(UUID.fromString(uuid(text(id))));var ticket=input.get("ticket_id");var end=input.get("planned_end_at");return new ChangeNoticeDraft(UUID.fromString(a.tenantId()),applicant,ticket.isNull()?null:UUID.fromString(uuid(text(ticket))),text(input.get("change_summary")),ManualWorklog.parseInstant(text(input.get("planned_start_at"))),end.isNull()?null:ManualWorklog.parseInstant(text(end)),targets);}
    static Map<String,Object> summaryDto(Snapshot s){var result=map("id",s.id(),"tenant_id",s.tenantId(),"version",s.version(),"archived",s.archived(),"recorded_by",s.recordedBy(),"created_at",s.createdAt().toString(),"updated_at",s.updatedAt().toString(),"recorded_at",s.recordedAt().toString());result.putAll(definitionDto(s.draft(),false));return result;}
    static Map<String,Object> dto(Snapshot s){var result=summaryDto(s);result.put("asset_ids",s.draft().assetIds().stream().map(UUID::toString).toList());result.put("change_summary",s.draft().changeSummary());return result;}
    static Map<String,Object> revisionDto(Revision r){var result=map("notice_id",r.noticeId(),"tenant_id",r.tenantId(),"version",r.version(),"previous_version",r.version()==1?null:r.version()-1,"action",r.action(),"archived",r.archived(),"recorded_by",r.recordedBy(),"recorded_at",r.recordedAt().toString());result.putAll(definitionDto(r.draft(),true));return result;}
    private static Map<String,Object> definitionDto(ChangeNoticeDraft d,boolean full){var result=map("applicant_id",d.applicantId().toString(),"ticket_id",d.ticketId()==null?null:d.ticketId().toString(),"asset_count",d.assetIds().size(),"planned_start_at",d.plannedStartAt().toString(),"planned_end_at",d.plannedEndAt()==null?null:d.plannedEndAt().toString(),"content_sha256",d.fingerprint(),"timezone",d.timezone(),"effective",false,"lifecycle_status","DRAFT","approval_status",null,"approval_workflow_status","CONFIG_PENDING","matching_policy_status","CONFIG_PENDING","automatic_p3_decision",null,"approval_evidence_verified",false,"device_execution_allowed",false,"alert_suppression_allowed",false,"source","postgresql","record_source","UNREVIEWED_CHANGE_NOTICE_DRAFT");if(full){result.put("asset_ids",d.assetIds().stream().map(UUID::toString).toList());result.put("change_summary",d.changeSummary());}return result;}
    private Access access(HttpServletRequest r,boolean write){if(r.getUserPrincipal()==null||r.getSession(false)==null)throw expired();Object value=r.getSession(false).getAttribute("mop.tenant_id");if(!(value instanceof String tenant)||tenant.isBlank())throw expired();String actor=r.getUserPrincipal().getName();var member=platform.membership(actor,tenant).orElseThrow(ChangeNoticeDraftController::expired);if(!member.active()||member.permissionVersion()<1)throw expired();if(!member.capabilities().contains(write?"change_notice_drafts:write":"change_notice_drafts:read"))throw new DomainException(403,"ACTION_FORBIDDEN","未生效变更报备草稿仅限当前授权平台管理员维护");return new Access(actor,tenant,member.permissionVersion(),trace(r));}
    static JsonNode body(HttpServletRequest request){try{if(request.getContentLengthLong()>MAX_BODY_BYTES)throw tooLarge();byte[] bytes=request.getInputStream().readNBytes(MAX_BODY_BYTES+1);if(bytes.length>MAX_BODY_BYTES)throw tooLarge();try(var parser=INPUT.getFactory().createParser(bytes)){int tokens=0;while(parser.nextToken()!=null)if(++tokens>4000)throw tooLarge();}return INPUT.readTree(bytes);}catch(DomainException e){throw e;}catch(Exception e){throw invalid();}}
    private static Map<String,String> query(HttpServletRequest r,Set<String> allowed){var result=new HashMap<String,String>();r.getParameterMap().forEach((key,values)->{if(!allowed.contains(key)||values.length!=1||values[0]==null||values[0].length()>64)throw invalid();result.put(key,values[0]);});return result;}
    private static int pageSize(Map<String,String> q){String value=q.getOrDefault("page_size","15");if(!Set.of("10","15","20").contains(value))throw invalid();return Integer.parseInt(value);}
    private static long version(String s){if(!s.matches("[1-9][0-9]{0,15}"))throw invalid();try{long v=Long.parseLong(s);if(v>MAX_VERSION)throw invalid();return v;}catch(NumberFormatException e){throw invalid();}}
    private static String uuid(String s){if(s==null||!s.matches("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"))throw invalid();return UUID.fromString(s).toString();}
    private static String text(JsonNode n){if(n==null||!n.isTextual())throw invalid();return n.textValue();}
    private static void fields(JsonNode n,Set<String> keys){if(n==null||!n.isObject()||n.size()!=keys.size())throw invalid();n.fieldNames().forEachRemaining(k->{if(!keys.contains(k))throw invalid();});}
    private static JsonNode canonical(JsonNode n){if(n.isArray()){var result=INPUT.createArrayNode();n.forEach(v->result.add(canonical(v)));return result;}if(!n.isObject())return n;var result=INPUT.createObjectNode();var keys=new TreeSet<String>();n.fieldNames().forEachRemaining(keys::add);for(String k:keys)result.set(k,canonical(n.get(k)));return result;}
    private static String hash(JsonNode n){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(INPUT.writeValueAsBytes(canonical(n))));}catch(Exception e){throw new IllegalStateException("Change notice request hash unavailable");}}
    private static DomainException invalid(){return new DomainException(400,"VALIDATION_ERROR","变更报备草稿字段、版本、目标或查询边界无效；不接受租户、申请人、批准、生效、P3或抑制覆盖");}
    private static DomainException tooLarge(){return new DomainException(413,"REQUEST_TOO_LARGE","变更报备草稿请求超出有界技术保护，未截断保存");}
    private static DomainException expired(){return new DomainException(401,"SESSION_EXPIRED","当前会话或成员关系已失效");}
}
